import sys
import asyncio
import time

from shiny import App, ui, render, reactive, Inputs, Outputs, Session
import pandas as pd
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from io import BytesIO
import base64

# Detect Pyodide environment
def is_pyodide():
    try:
        import js  # type: ignore
        return True
    except ImportError:
        return False

# Fake psutil for Pyodide
if is_pyodide():
    import random
    class FakePsutil:
        @staticmethod
        def cpu_percent(interval=None):
            return random.uniform(0, 100)
    psutil = FakePsutil()
else:
    import psutil

# Hide axis ticks utility
def hide_ticks(ax):
    ax.set_xticks([])
    ax.set_yticks([])

# Available matplotlib colormaps
COLORMAPS = sorted([
    m for m in plt.colormaps()
    if not m.endswith("_r") and not m.startswith("tab")
])

app_ui = ui.page_sidebar(
    ui.sidebar(
        ui.input_select("colormap", "Colormap", COLORMAPS, selected="viridis"),
        ui.input_action_button("clear", "Clear History"),
        ui.input_action_button("freeze", "Freeze Output"),
        ui.input_numeric("samples", "Samples per Graph", 30, min=5, max=200),
        ui.input_numeric("rows", "Rows in Table", 10, min=1, max=200),
        width=300
    ),
    ui.layout_column_wrap(
        width=1/2,
        ui.card(
            ui.card_header("CPU Usage Graph"),
            ui.output_plot("cpu_plot", height="350px")
        ),
        ui.card(
            ui.card_header("CPU Usage Table"),
            ui.output_table("cpu_table")
        )
    )
)

class CpuHistory:
    def __init__(self):
        self.data = []
        self.timestamps = []
        self.frozen = False

    def add(self, value):
        if not self.frozen:
            self.data.append(value)
            self.timestamps.append(time.strftime("%H:%M:%S"))

    def clear(self):
        self.data.clear()
        self.timestamps.clear()

    def freeze(self):
        self.frozen = not self.frozen

    def get(self, n):
        return self.timestamps[-n:], self.data[-n:]

    def as_dataframe(self, n):
        ts, vals = self.get(n)
        return pd.DataFrame({"Time": ts, "CPU (%)": vals})

cpu_history = CpuHistory()

async def poll_cpu():
    while True:
        await asyncio.sleep(1)
        cpu = psutil.cpu_percent(interval=None)
        cpu_history.add(cpu)

def freeze_label():
    return "Unfreeze Output" if cpu_history.frozen else "Freeze Output"

def server(input: Inputs, output: Outputs, session: Session):
    # Start polling in background
    if not is_pyodide():
        asyncio.create_task(poll_cpu())
    else:
        # In Pyodide, use setInterval via js
        import js
        def poll():
            cpu = psutil.cpu_percent()
            cpu_history.add(cpu)
        js.setInterval(poll, 1000)

    @reactive.Effect
    @reactive.event(input.clear)
    def _():
        cpu_history.clear()

    @reactive.Effect
    @reactive.event(input.freeze)
    def _():
        cpu_history.freeze()
        session.send_input_message("freeze", {"label": freeze_label()})

    @reactive.Effect
    def _():
        # Update freeze button label
        session.send_input_message("freeze", {"label": freeze_label()})

    @output
    @render.plot(alt="CPU Usage Plot")
    def cpu_plot():
        n = int(input.samples())
        colormap = input.colormap()
        ts, vals = cpu_history.get(n)
        fig, ax = plt.subplots(figsize=(6, 3))
        if vals:
            points = ax.scatter(range(len(vals)), vals, c=vals, cmap=colormap, s=60)
            ax.plot(range(len(vals)), vals, color="gray", alpha=0.5)
            ax.set_ylim(0, 100)
            ax.set_ylabel("CPU (%)")
            ax.set_xlabel("Sample")
            hide_ticks(ax)
            fig.colorbar(points, ax=ax, label="CPU (%)")
            ax.set_title("CPU Usage (%)")
        else:
            ax.text(0.5, 0.5, "No data", ha="center", va="center", fontsize=16)
            hide_ticks(ax)
        plt.tight_layout()
        return fig

    @output
    @render.table
    def cpu_table():
        n = int(input.rows())
        df = cpu_history.as_dataframe(n)
        return df[::-1]  # Show most recent first

    @session.on_input_message
    def on_input_message(msg):
        # Update freeze button label if needed
        if msg["input"] == "freeze" and "label" in msg["data"]:
            session.send_custom_message("update_freeze_label", msg["data"]["label"])

    @session.on_custom_message
    def on_custom_message(msg):
        # Not used, but could be for further extension
        pass

app = App(app_ui, server)
